// Package services holds the Wails-bound service structs — hive's typed IPC
// boundary, the equivalent of papr's src-tauri/src/commands.rs. Every exported
// method on a registered service becomes a frontend-callable command (with TS
// bindings generated by `wails3 generate bindings`). Services delegate all SQL
// to internal/db and never embed raw queries.
package services

import (
	"context"

	"hive/internal/appstate"
	"hive/internal/db"
)

// Services bundles every bound service so main.go can register them in one place.
type Services struct {
	Folder     *FolderService
	Feed       *FeedService
	Article    *ArticleService
	Tag        *TagService
	Rule       *RuleService
	Setting    *SettingService
	Highlight  *HighlightService
	Storage    *StorageService
	System     *SystemService
	AI         *AIService
	Sync       *SyncService
	Opml       *OpmlService
	Newsletter *NewsletterService
	PageView   *PageViewService
	Font       *FontService
}

// New constructs every service over the shared application state.
func New(app *appstate.State) *Services {
	return &Services{
		Folder:     &FolderService{app: app},
		Feed:       &FeedService{app: app},
		Article:    &ArticleService{app: app},
		Tag:        &TagService{app: app},
		Rule:       &RuleService{app: app},
		Setting:    &SettingService{app: app},
		Highlight:  &HighlightService{app: app},
		Storage:    &StorageService{app: app},
		System:     &SystemService{app: app},
		AI:         &AIService{app: app},
		Sync:       &SyncService{app: app},
		Opml:       &OpmlService{app: app},
		Newsletter: &NewsletterService{app: app},
		PageView:   &PageViewService{},
		Font:       &FontService{app: app},
	}
}

// bg is the background context used by non-cancellable command handlers.
func bg() context.Context { return context.Background() }

// truncateRunes returns at most max runes of s without splitting a UTF-8
// boundary. Mirrors commands.rs truncate.
func truncateRunes(s string, max int) string {
	r := []rune(s)
	if len(r) <= max {
		return s
	}
	return string(r[:max])
}

// enqueueIfConnected queues a read/starred change for the sync server, but only
// when a server is linked. Mirrors commands.rs enqueue_if_connected.
func enqueueIfConnected(ctx context.Context, q db.Querier, id int64, field string, value bool) {
	if db.IsFreshrssConnected(ctx, q) {
		_ = db.EnqueueSync(ctx, q, id, field, value)
	}
}
